    iron_gardenleafgrabber = { name = "Železni grablje za liste", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni grablje za liste za vrtnarje." },
    bronze_gardenleafgrabber = { name = "Bronast grablje za liste", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast grablje za liste za vrtnarje." },
