    gilded_gardenleafgrabber = { name = "Pozlačen grablje za liste", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen grablje za liste za vrtnarje." },
    jewel_set_gardenleafgrabber = { name = "Draguljast grablje za liste", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast grablje za liste za vrtnarje." },
    royal_sovereign_gardenleafgrabber = { name = "Kraljevski suveren grablje za liste", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren grablje za liste z biseri za krono." },
}
local BUILDINGS = {
    gardenleafgrabber_workshop = { name = "Gardenleafgrabber delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
